import 'package:flutter/material.dart';

import 'asl_motion_catalog.dart';
import 'english_to_asl_service.dart';
import 'realistic_avatar_stage.dart';

class TextToSignScreen extends StatefulWidget {
  const TextToSignScreen({super.key, this.approvedUtteranceId});

  /// Phase 2 integration point: a stable, reviewed ASL utterance ID. This is
  /// deliberately not English text or a gloss generated by this screen.
  final String? approvedUtteranceId;

  @override
  State<TextToSignScreen> createState() => _TextToSignScreenState();
}

class _TextToSignScreenState extends State<TextToSignScreen> {
  final _textController = TextEditingController();
  double _speed = 1;
  bool _playing = false;
  bool _modelReady = false;
  int _replayToken = 0;
  List<String> _availableClips = const [];
  List<AslMotionStep> _sequence = const [];
  int _sequenceIndex = 0;
  String? _activeClip;
  int? _activeDurationMs;
  int _activeTransitionMs = 150;
  String _status = 'جارٍ تحميل نموذج الأفاتار…';
  AslMotionCatalog? _catalog;
  EnglishToAslService? _translationService;
  AslTranslationResult? _translationResult;
  AvatarRigAudit? _rigAudit;

  @override
  void initState() {
    super.initState();
    _loadCatalog();
  }

  @override
  void didUpdateWidget(covariant TextToSignScreen oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.approvedUtteranceId != widget.approvedUtteranceId) {
      _tryPlayApprovedUtterance();
    }
  }

  Future<void> _loadCatalog() async {
    try {
      final catalog = await AslMotionCatalog.load();
      final translationService = await EnglishToAslService.load(catalog);
      if (!mounted) return;
      setState(() {
        _catalog = catalog;
        _translationService = translationService;
      });
      _tryPlayApprovedUtterance();
    } catch (error) {
      if (mounted) {
        setState(() => _status = 'تعذر تحميل كتالوج الحركات: $error');
      }
    }
  }

  @override
  void dispose() {
    _textController.dispose();
    super.dispose();
  }

  void _playSentence() {
    if (_textController.text.trim().isEmpty) {
      setState(() {
        _playing = false;
        _activeClip = null;
        _sequence = const [];
        _translationResult = null;
        _status = 'اكتبي جملة باللغة الإنجليزية أولًا.';
      });
      return;
    }
    final translator = _translationService;
    final catalog = _catalog;
    if (translator == null || catalog == null) {
      setState(() => _status = 'موارد الترجمة المحلية لم تكتمل بعد.');
      return;
    }
    final result = translator.translate(
      _textController.text,
      availableClips: _availableClips.toSet(),
    );
    final plan = AslSequenceBuilder(catalog)
        .build(result, availableClips: _availableClips.toSet());
    final playbackBlocker = plan != null
        ? !_modelReady
              ? 'لن يبدأ التشغيل حتى يكتمل تحميل الأفاتار.'
              : _rigAudit?.isStructurallyValid != true
              ? 'لن يبدأ التشغيل قبل اجتياز فحص هيكل الريغ.'
              : null
        : null;
    setState(() {
      _playing = false;
      _activeClip = null;
      _sequence = const [];
      _translationResult = result;
      if (plan == null || playbackBlocker != null) {
        _status = playbackBlocker ?? result.message;
        return;
      }
      _sequence = plan.steps;
      _sequenceIndex = 0;
      _setActiveStep(plan.steps.first);
      _replayToken++;
      _playing = true;
      _status = result.message;
    });
  }

  void _tryPlayApprovedUtterance() {
    final utteranceId = widget.approvedUtteranceId;
    if (utteranceId == null || utteranceId.trim().isEmpty) return;
    if (!_modelReady || _catalog == null) return;
    if (_rigAudit?.isStructurallyValid != true) {
      setState(() {
        _playing = false;
        _status = 'توقّف التشغيل: لم يجتز هيكل الريغ فحص المطابقة البنيوي.';
      });
      return;
    }
    final plan = _catalog!.resolveUtterance(
      utteranceId,
      _availableClips.toSet(),
    );
    if (plan == null) {
      setState(() {
        _playing = false;
        _activeClip = null;
        _sequence = const [];
        _status = 'معرّف تسلسل ASL غير متاح أو غير معتمد بالكامل؛ لن نشغّل حركة تخمينية.';
      });
      return;
    }
    setState(() {
      _sequence = plan.steps;
      _sequenceIndex = 0;
      _setActiveStep(plan.steps.first);
      _replayToken++;
      _playing = true;
      _status = 'تشغيل تسلسل ASL المراجع ${plan.utteranceId} (${plan.gloss}).';
    });
  }

  void _setActiveStep(AslMotionStep step) {
    _activeClip = step.clipId;
    _activeDurationMs = step.durationMs;
    _activeTransitionMs = step.transitionMs;
  }

  void _onClipFinished() {
    if (!mounted) return;
    setState(() {
      if (_sequenceIndex + 1 < _sequence.length) {
        _sequenceIndex++;
        _setActiveStep(_sequence[_sequenceIndex]);
        _replayToken++;
        _playing = true;
      } else {
        _playing = false;
        _status = 'انتهى تشغيل التسلسل. يلزم التحقق البصري المستقل قبل اعتباره متحققًا.';
      }
    });
  }

  void _stopPlayback() {
    if (!mounted) return;
    setState(() {
      _playing = false;
      _sequence = const [];
      _sequenceIndex = 0;
      _activeClip = null;
      _activeDurationMs = null;
      _activeTransitionMs = 150;
      _status = 'تم إيقاف التشغيل.';
    });
  }

  Widget _readinessRow(String label, bool ready, {String? detail}) => Padding(
    padding: const EdgeInsets.symmetric(vertical: 3),
    child: Row(
      children: [
        Icon(
          ready ? Icons.check_circle : Icons.pending_outlined,
          size: 18,
          color: ready ? Colors.green.shade700 : Colors.blueGrey,
        ),
        const SizedBox(width: 8),
        Expanded(child: Text(detail == null ? label : '$label — $detail')),
      ],
    ),
  );

  @override
  Widget build(BuildContext context) {
    final hasSequence = _sequence.isNotEmpty;
    final clips = _availableClips.toSet();
    final approvedClipCount = _catalog?.approvedClipCount(clips) ?? 0;
    final approvedUtteranceCount = _catalog?.approvedUtteranceCount(clips) ?? 0;
    return Scaffold(
      appBar: AppBar(
        title: const Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          mainAxisSize: MainAxisSize.min,
          children: [
            Text('SignTalk'),
            Text(
              'English → American Sign Language',
              style: TextStyle(fontSize: 12, fontWeight: FontWeight.normal),
            ),
          ],
        ),
      ),
      body: ListView(
        padding: const EdgeInsets.fromLTRB(16, 8, 16, 24),
        children: [
          SizedBox(
            height: MediaQuery.sizeOf(context).height * .43,
            child: RealisticAvatarStage(
              playing: _playing,
              speed: _speed,
              replayToken: _replayToken,
              animationName: _activeClip,
              durationMs: _activeDurationMs,
              transitionMs: _activeTransitionMs,
              onModelReady: (ready) {
                if (!mounted) return;
                setState(() {
                  _modelReady = ready;
                  if (ready) _status = 'تم تحميل النموذج؛ فحص الريغ والحركات يعرض حالتهما أدناه.';
                });
                if (ready) _tryPlayApprovedUtterance();
              },
              onRigAudit: (audit) {
                if (!mounted) return;
                setState(() => _rigAudit = audit);
                _tryPlayApprovedUtterance();
              },
              onClipsReady: (clips) {
                if (!mounted) return;
                setState(() => _availableClips = clips);
                _tryPlayApprovedUtterance();
              },
              onFinished: _onClipFinished,
              onError: (error) {
                if (mounted) {
                  setState(() {
                    _playing = false;
                    _status = error;
                  });
                }
              },
            ),
          ),
          const SizedBox(height: 10),
          Card(
            child: Padding(
              padding: const EdgeInsets.all(12),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    'حالة المرحلة الأولى',
                    style: Theme.of(context).textTheme.titleSmall,
                  ),
                  const SizedBox(height: 5),
                  _readinessRow('النموذج محمّل', _modelReady),
                  _readinessRow(
                    'بنية الريغ ومسارات التشخيص مطابقة',
                    _rigAudit?.isStructurallyValid == true,
                    detail: _rigAudit == null
                        ? 'بانتظار الفحص'
                        : 'أصابع ${_rigAudit!.fingerJointsFound}/${_rigAudit!.fingerJointCount}، '
                              'مسارات الأصابع ${_rigAudit!.fingerJointsAnimated}/${_rigAudit!.fingerJointCount}، '
                              'مسارات الجسم ${_rigAudit!.bodyJointsAnimated}/${_rigAudit!.bodyJointCount}، '
                              'تعابير ${_rigAudit!.faceTargetsFound}/${_rigAudit!.faceTargetCount}، '
                              'مسار الوجه ${_rigAudit!.hasFaceAnimationTrack ? 'موجود' : 'مفقود'}'
                              '${_rigAudit!.issues.isEmpty ? '' : '؛ ${_rigAudit!.issues.join('، ')}'}',
                  ),
                  _readinessRow('كتالوج الحركات محمّل', _catalog != null),
                  _readinessRow(
                    'مقاطع ASL المراجعة متاحة',
                    approvedClipCount > 0,
                    detail: '$approvedClipCount',
                  ),
                  _readinessRow(
                    'مراجعة ASL موجودة على المقاطع',
                    approvedClipCount > 0,
                  ),
                  _readinessRow(
                    'تسلسلات ASL معتمدة ومتاحة',
                    approvedUtteranceCount > 0,
                    detail: '$approvedUtteranceCount',
                  ),
                  _readinessRow('التشغيل الكامل متحقق بصريًا', false),
                ],
              ),
            ),
          ),
          const SizedBox(height: 14),
          TextField(
            controller: _textController,
            minLines: 2,
            maxLines: 4,
            textCapitalization: TextCapitalization.sentences,
            textInputAction: TextInputAction.done,
            onSubmitted: (_) => _playSentence(),
            decoration: const InputDecoration(
              labelText: 'اكتبي الجملة بالإنجليزية',
              hintText: 'For example: Hello, how are you?',
              prefixIcon: Icon(Icons.keyboard_alt_outlined),
            ),
          ),
          const SizedBox(height: 12),
          FilledButton.icon(
            onPressed: _playSentence,
            icon: const Icon(Icons.play_arrow_rounded),
            label: const Text('ترجمة إلى ASL'),
          ),
          if (_translationResult case final result?) ...[
            const SizedBox(height: 8),
            Card(
              child: Padding(
                padding: const EdgeInsets.all(12),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      'حالة الترجمة: ${_translationStatusLabel(result.status)}',
                    ),
                    const SizedBox(height: 4),
                    Text(
                      'التحليل السطحي: ${result.analysis.detectedFeatures.isEmpty ? 'لم تُرصد علامات بنيوية بسيطة' : result.analysis.detectedFeatures.join('، ')}',
                    ),
                    Text(
                      'الضمائر: ${result.analysis.pronouns.isEmpty ? '—' : result.analysis.pronouns.join('، ')}',
                    ),
                    Text(
                      'مرشح الفاعل في التحليل السطحي: ${result.analysis.subjectCandidate ?? '—'}',
                    ),
                    Text(
                      'مرشح المفعول في التحليل السطحي: ${result.analysis.objectCandidate ?? '—'}',
                    ),
                    Text(
                      'تعبيرات الزمن: ${result.analysis.timeExpressions.isEmpty ? '—' : result.analysis.timeExpressions.join('، ')}',
                    ),
                    Text('مراجعة الترجمة: ${result.reviewStatus}'),
                    Text(
                      'المصدر: ${result.translationSource ?? 'غير متوفر؛ الترجمة بانتظار المراجعة'}',
                    ),
                    if (result.gloss != null)
                      Text('ASL Gloss المراجع: ${result.gloss!.text}'),
                    Text(
                      'الإشارات المتاحة: ${result.availableSignIds.isEmpty ? '—' : result.availableSignIds.join('، ')}',
                    ),
                    if (result.missingSignIds.isNotEmpty)
                      Text(
                        'الإشارات الناقصة: ${result.missingSignIds.join('، ')}',
                      ),
                    Text(
                      'العلامات غير اليدوية: ${result.reviewStatus == 'approved' ? (result.nonManualMarkers.isEmpty ? 'لا توجد مسجلة' : result.nonManualMarkers.join('، ')) : 'بانتظار مراجعة لغوية'}',
                    ),
                    Text(
                      'مؤهل للتشغيل الكامل: ${result.isPlaybackEligible ? 'نعم' : 'لا'}',
                    ),
                    const SizedBox(height: 4),
                    Text(result.message),
                  ],
                ),
              ),
            ),
          ],
          const SizedBox(height: 8),
          Row(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              IconButton.filledTonal(
                tooltip: _playing ? 'إيقاف مؤقت' : 'متابعة',
                onPressed: hasSequence
                    ? () => setState(() => _playing = !_playing)
                    : null,
                icon: Icon(_playing ? Icons.pause : Icons.play_arrow),
              ),
              const SizedBox(width: 12),
              IconButton.filledTonal(
                tooltip: 'إعادة',
                onPressed: hasSequence
                    ? () => setState(() {
                        _sequenceIndex = 0;
                        _setActiveStep(_sequence.first);
                        _replayToken++;
                        _playing = true;
                      })
                    : null,
                icon: const Icon(Icons.replay),
              ),
              const SizedBox(width: 12),
              IconButton.filledTonal(
                tooltip: 'إيقاف',
                onPressed: hasSequence ? _stopPlayback : null,
                icon: const Icon(Icons.stop),
              ),
            ],
          ),
          Row(
            children: [
              const Text('السرعة'),
              Expanded(
                child: Slider(
                  value: _speed,
                  min: .5,
                  max: 1.5,
                  divisions: 4,
                  onChanged: (value) => setState(() => _speed = value),
                ),
              ),
              Text('${_speed.toStringAsFixed(1)}×'),
            ],
          ),
          Container(
            padding: const EdgeInsets.all(12),
            decoration: BoxDecoration(
              color: const Color(0xFFEAF3F8),
              borderRadius: BorderRadius.circular(14),
            ),
            child: Text(_status, textAlign: TextAlign.center),
          ),
        ],
      ),
    );
  }

  String _translationStatusLabel(AslTranslationStatus status) =>
      switch (status) {
        AslTranslationStatus.ready => 'جاهزة من مورد مراجع',
        AslTranslationStatus.pendingReview => 'بانتظار مراجعة ASL',
        AslTranslationStatus.unsupported => 'لا توجد ترجمة مراجعة',
        AslTranslationStatus.incompleteMotion => 'تسلسل الإشارات غير مكتمل',
      };
}
